const c = $input.first().json; const items = [];
for (const p of c.platforms) {
  if (c.cached && c.cached[p]) continue;                                   // fresh cached research is reused (refreshed every policy_refresh_days)
  for (const u of (c.policy_urls[p] || [])) { if (/^https:\/\//.test(u)) items.push({ json: { platform: p, url: u } }); }
}
return items.length ? items : [{ json: { none: true, cache_ok: c.platforms.every(p => c.cached && c.cached[p]) } }];

const plan = $('Plan Policy Fetch').all().map(i => i.json);
const byPlat = {}; $input.all().forEach((it, i) => { const p = plan[i]?.platform; if (!p) return;
  const txt = String(it.json.data ?? it.json).replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 9000);
  byPlat[p] = (byPlat[p] || []).concat([{ url: plan[i].url, text: txt }]); });
const c = $('Policy Context').first().json; const job = $('Load Job').first().json;
const prompt = `Assess each platform ONLY from the provided policy text (and cached summaries). If the text does not address something, mark it unknown - do not guess.\n` +
 `Source: "${c.title}" by ${c.creator}. Rights record: ${JSON.stringify(c.permission || {})}\nPlatforms: ${c.platforms.join(', ')}\n` +
 `Cached summaries: ${JSON.stringify(c.cached || {})}\nFetched policy text: ${JSON.stringify(byPlat)}\n\n` +
 `Return JSON {"assessments":[{"platform":str,"monetization_status":"pass|conditional|review_required|blocked","policy_risk":"low|medium|high|unknown","reasons":[str],"required_actions":[str],"evidence":[{"url":str,"note":str}]}]}. ` +
 `Remember: permission to use content is NOT monetization eligibility. Never write "guaranteed", "definitely safe".`;
return [{ json: { prompt, system: 'You are a cautious platform-policy analyst. Output valid JSON only. Uncertain => review_required.', byPlat, fetched: Object.keys(byPlat).length > 0 } }];

const c = $('Policy Context').first().json;
const a = c.platforms.map(p => ({ platform: p, rights_status: c.permission?.permission_status || 'unknown', monetization_status: 'review_required', policy_risk: 'unknown',
  reasons: ['No official policy source URLs are configured (settings.policy_source_urls) and no fresh cached research exists'], required_actions: ['Configure policy_source_urls for ' + p + ' or review the platform policy manually'], evidence: [], checked_at: new Date().toISOString() }));
return [{ json: { assessments: a } }];

// Normalize an error output into {job_id, category, message}. Secrets are redacted before anything is persisted.
const j = $input.first().json;
const jobId = $('Load Job').first().json.job_id;
const raw = JSON.stringify(j.error ?? j).slice(0, 700);
const m = raw.match(/\b([45]\d\d)\b/); const code = m ? +m[1] : 0;
let cat = 'UNKNOWN';
if (/VALIDATION:/.test(raw)) cat = 'VALIDATION';
else if (/RIGHTS:/.test(raw)) cat = 'RIGHTS';
else if (code === 401 || code === 403 || /unauthori|invalid_grant|token (has )?expired|permission|credentials/i.test(raw)) cat = 'AUTH';
else if (code === 429 || /quota|rate.?limit|RESOURCE_EXHAUSTED/i.test(raw)) cat = 'RATE_LIMIT';
else if (code >= 500 || /ECONN|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|socket hang|timed? ?out/i.test(raw)) cat = 'TRANSIENT';
else if (code >= 400) cat = 'VALIDATION';
const msg = raw.replace(/(api[_-]?key|key|token|secret|authorization|bearer)["'=: ]+[A-Za-z0-9._\-]{8,}/gi, '$1=[redacted]');
return [{ json: { job_id: jobId, category: cat, message: msg } }];

const m = $json; const p = $('Assemble Policy Text').first().json;
const body = { system: p.system, prompt: p.prompt };
return [{ json: { provider: m.provider, model: m.model, kind: m.kind, base_url: (m.base_url || '').replace(/\/+$/, ''), body } }];

const meta = $('Build LLM Request').first().json; const r = $input.first().json;
let text = '';
if (meta.kind === 'gemini') text = r.candidates?.[0]?.content?.parts?.map(p => p.text).join('') ?? '';
else if (meta.kind === 'openai_compat') text = r.choices?.[0]?.message?.content ?? '';
else text = r.message?.content ?? '';
text = String(text).replace(/^```json|```$/gim, '').trim();
let data; try { data = JSON.parse(text); } catch (e) { throw new Error('VALIDATION: model returned non-JSON output'); }
return [{ json: { data, provider: meta.provider, model: meta.model } }];

